/* Core Dermatology for the GP AKT: 70 single-best-answer questions, generated by tools/make_derm_bank.py */
const DERM_BANK=[{"id": "derm-t01#0", "cat": "dermatology", "topic": "Rosacea", "s": "A 42-year-old woman has a 2-year history of central facial redness, flushing after wine and hot drinks, and visible telangiectasia on the cheeks. There are no papules, pustules or comedones. Eyes are asymptomatic. What is the most appropriate initial management?", "o": ["Oral doxycycline 100 mg daily", "Hydrocortisone 1% cream twice daily", "Clinical diagnosis of rosacea with trigger avoidance, sunscreen and emollient", "Refer for blood tests for lupus", "Topical ivermectin 1% cream"], "a": 2, "e": "Clinical diagnosis of rosacea with trigger avoidance, sunscreen and emollient. Typical erythematotelangiectatic rosacea. Diagnosis is clinical and general measures come first. Antibiotics and ivermectin target inflammatory lesions, which are absent. Steroids worsen rosacea.", "src": null}, {"id": "derm-t01#1", "cat": "dermatology", "topic": "Rosacea", "s": "A 35-year-old man has central facial erythema with scattered papules and pustules on the cheeks and nose. There are no comedones. Which is the most appropriate first-line treatment?", "o": ["Topical ivermectin 1% cream once daily", "Oral isotretinoin", "Topical benzoyl peroxide with adapalene", "Brimonidine 0.33% gel", "Topical clobetasol"], "a": 0, "e": "Topical ivermectin 1% cream once daily. Mild-moderate papulopustular rosacea: topical ivermectin once daily (or azelaic acid or metronidazole). Absence of comedones makes acne unlikely. Brimonidine does not treat pustules.", "src": null}, {"id": "derm-t01#2", "cat": "dermatology", "topic": "Rosacea", "s": "A 48-year-old woman with papulopustular rosacea has used topical ivermectin daily for 12 weeks with little improvement and persisting inflammatory lesions. What is the next best step?", "o": ["Stop all treatment", "Add oral doxycycline alongside topical treatment", "Start topical hydrocortisone", "Prescribe brimonidine", "Reassure and review in 1 year"], "a": 1, "e": "Add oral doxycycline alongside topical treatment. Inadequate response to topical therapy in inflammatory disease: add an oral tetracycline (for example doxycycline 100 mg daily, or lymecycline 408 mg daily) for about 6-12 weeks.", "src": null}, {"id": "derm-t01#3", "cat": "dermatology", "topic": "Rosacea", "s": "A 29-year-old woman, 12 weeks pregnant, has papulopustular rosacea. Which approach is most appropriate?", "o": ["Doxycycline 100 mg daily", "Lymecycline 408 mg daily", "Topical ivermectin", "Topical metronidazole", "Oral tetracycline plus brimonidine"], "a": 3, "e": "Topical metronidazole. Avoid tetracyclines in pregnancy. Ivermectin should be avoided unless specifically advised after assessment. Topical metronidazole is a commonly considered option. If systemic treatment is needed, seek specialist/local guidance (erythromycin may be supported).", "src": null}, {"id": "derm-t01#4", "cat": "dermatology", "topic": "Rosacea", "s": "A 55-year-old man has persistent facial redness and telangiectasia for years. He has no papules or pustules and is bothered by the appearance. Which treatment is most appropriate to reduce the redness?", "o": ["Oral doxycycline", "Topical brimonidine 0.33% gel", "Topical metronidazole only", "Oral prednisolone", "Topical hydrocortisone"], "a": 1, "e": "Topical brimonidine 0.33% gel. Persistent vascular erythema without inflammatory lesions: brimonidine gives temporary reduction in redness. Camouflage and laser/IPL are options. Antibiotics do not reliably treat vascular redness.", "src": null}, {"id": "derm-t01#5", "cat": "dermatology", "topic": "Rosacea", "s": "A 45-year-old man with rosacea reports gritty, dry eyes and crusting of the eyelid margins. Visual acuity is normal and there is no eye pain or photophobia. What is the most appropriate management?", "o": ["Urgent same-day ophthalmology referral", "Lid hygiene, warm compresses and ocular lubricants", "Topical steroid eye drops", "Oral isotretinoin", "No treatment needed"], "a": 1, "e": "Lid hygiene, warm compresses and ocular lubricants. Blepharitis in ocular rosacea without red flags: lid hygiene, warm compresses, lubricants and assess severity. Consider ophthalmology if persistent or severe.", "src": null}, {"id": "derm-t01#6", "cat": "dermatology", "topic": "Rosacea", "s": "A 50-year-old woman with known rosacea develops a painful red right eye with photophobia and blurred vision. What is the most appropriate action?", "o": ["Reassure that this is ocular rosacea", "Increase lid hygiene and review in 4 weeks", "Prescribe oral doxycycline and review in 12 weeks", "Urgent ophthalmology assessment", "Start topical brimonidine"], "a": 3, "e": "Urgent ophthalmology assessment. Pain, photophobia and reduced vision suggest keratitis or corneal involvement and need urgent ophthalmological assessment. Do not assume it is benign ocular rosacea.", "src": null}, {"id": "derm-t01#7", "cat": "dermatology", "topic": "Rosacea", "s": "A 38-year-old woman was given hydrocortisone 1% cream by a pharmacy for facial redness and now has worsening erythema, papules and pustules. What is the most appropriate next step?", "o": ["Increase the steroid potency", "Stop the topical steroid and manage as rosacea/steroid-induced rosacea-like dermatitis", "Start a topical antifungal", "Start oral prednisolone", "Refer for allergy testing"], "a": 1, "e": "Stop the topical steroid and manage as rosacea/steroid-induced rosacea-like dermatitis. Topical corticosteroids aggravate rosacea and can cause a steroid-induced rosacea-like dermatitis. Stop the steroid, give general measures and treat the inflammatory features as appropriate. Be prepared for a flare on withdrawal.", "src": null}, {"id": "derm-t01#8", "cat": "dermatology", "topic": "Rosacea", "s": "A 62-year-old man has longstanding rosacea with a thickened, irregular, bulbous nose. He asks if antibiotics will reduce the nasal enlargement. What is the most appropriate management?", "o": ["Long-term doxycycline", "Topical brimonidine", "Dermatology / plastic surgery assessment", "Topical hydrocortisone", "Reassurance and discharge"], "a": 2, "e": "Dermatology / plastic surgery assessment. Established rhinophyma is a structural change. Antibiotics do not reverse it, and procedural or surgical treatment may be needed, so refer to dermatology or plastic surgery.", "src": null}, {"id": "derm-t01#9", "cat": "dermatology", "topic": "Rosacea", "s": "A 40-year-old woman has episodes of facial flushing with loose stools and wheeze. Examination is unremarkable and there are no papules, pustules or telangiectasia. What is the most appropriate next step?", "o": ["Diagnose rosacea and start ivermectin", "Start doxycycline for presumed rosacea", "Consider carcinoid syndrome and arrange further assessment", "Prescribe brimonidine", "Advise sunscreen and discharge"], "a": 2, "e": "Consider carcinoid syndrome and arrange further assessment. Flushing with diarrhoea and wheeze is atypical for rosacea and suggests an alternative diagnosis such as carcinoid syndrome. Investigate and refer as appropriate rather than labelling it rosacea.", "src": null}, {"id": "derm-t02#0", "cat": "dermatology", "topic": "Psoriasis", "s": "A 44-year-old man has well-demarcated, scaly erythematous plaques on his elbows, knees and trunk covering about 4% of his body surface area. He has had no previous treatment. What is the most appropriate initial topical treatment?", "o": ["Emollient only", "Calcipotriol with betamethasone dipropionate once daily for up to 4 weeks", "Clobetasol propionate twice daily for 3 months", "Oral prednisolone", "Topical tacrolimus"], "a": 1, "e": "Calcipotriol with betamethasone dipropionate once daily for up to 4 weeks. Trunk and limb plaque psoriasis in adults: potent steroid plus vitamin D analogue once daily for up to 4 weeks. Emollients are supportive only. Prolonged potent steroid and oral steroids are inappropriate.", "src": null}, {"id": "derm-t02#1", "cat": "dermatology", "topic": "Psoriasis", "s": "A 19-year-old develops numerous small, drop-shaped scaly lesions on the trunk 2 weeks after a sore throat. The throat is now normal. What is the most appropriate management?", "o": ["Phenoxymethylpenicillin for 10 days", "Oral prednisolone", "Emollients and reassurance; refer to dermatology if extensive or persistent", "Methotrexate", "Potent steroid on the face"], "a": 2, "e": "Emollients and reassurance; refer to dermatology if extensive or persistent. Guttate psoriasis often follows streptococcal infection and is frequently self-limiting. Antibiotics do not reliably clear it and are not given automatically. Swab and treat only if there is current evidence of infection. Extensive or persistent disease may need phototherapy.", "src": null}, {"id": "derm-t02#2", "cat": "dermatology", "topic": "Psoriasis", "s": "A 38-year-old woman has psoriasis affecting her face. What is the most appropriate topical steroid strategy?", "o": ["Clobetasol propionate daily for 4 weeks", "Betamethasone dipropionate twice daily", "Mild or moderate potency steroid for a maximum of 2 weeks", "Very potent steroid with occlusion", "No treatment is suitable"], "a": 2, "e": "Mild or moderate potency steroid for a maximum of 2 weeks. Face, flexures and genitals have thin skin and greater risk of atrophy: use a mild/moderate steroid, maximum 2 weeks. Avoid potent and very potent steroids.", "src": null}, {"id": "derm-t02#3", "cat": "dermatology", "topic": "Psoriasis", "s": "A 50-year-old man with long-standing psoriasis becomes acutely unwell with fever and widespread sterile pustules on red skin. Which is the most appropriate action?", "o": ["Routine dermatology referral", "Topical emollient and review in 1 week", "Oral flucloxacillin", "Same-day specialist/emergency hospital assessment", "Start methotrexate in primary care"], "a": 3, "e": "Same-day specialist/emergency hospital assessment. Generalised pustular psoriasis is a dermatological emergency with risk of fluid and electrolyte disturbance and systemic illness. Same-day specialist assessment.", "src": null}, {"id": "derm-t02#4", "cat": "dermatology", "topic": "Psoriasis", "s": "A 41-year-old with plaque psoriasis reports morning stiffness, a completely swollen painful toe and heel pain. He has nail pitting. What is the most appropriate next step?", "o": ["Regular NSAIDs and review in 3 months", "Reassure that this is gout", "Prompt rheumatology referral", "Start potent topical steroids", "Request HLA-B27 and wait"], "a": 2, "e": "Prompt rheumatology referral. Dactylitis, enthesitis, nail pitting and morning stiffness suggest psoriatic arthritis. Refer promptly to rheumatology. Do not rely on repeated NSAIDs or wait for deformity.", "src": null}, {"id": "derm-t02#5", "cat": "dermatology", "topic": "Psoriasis", "s": "A 55-year-old woman is started on methotrexate for severe plaque psoriasis by dermatology. Which counselling or monitoring point is correct?", "o": ["Take it daily with food", "Take it once weekly; folic acid usually on a different day; monitor FBC, LFTs and renal function", "No blood monitoring is needed", "It is safe in pregnancy", "Take it with large amounts of alcohol"], "a": 1, "e": "Take it once weekly; folic acid usually on a different day; monitor FBC, LFTs and renal function. Methotrexate is weekly. Accidental daily dosing can be fatal. Monitor FBC, LFTs and renal function, limit alcohol, and avoid in pregnancy and breastfeeding.", "src": null}, {"id": "derm-t02#6", "cat": "dermatology", "topic": "Psoriasis", "s": "A 33-year-old has thick adherent scale on the scalp, extending slightly beyond the hairline. What is the most appropriate treatment?", "o": ["Potent steroid scalp formulation once daily for up to 4 weeks, with a descaling preparation if scale prevents penetration", "Oral prednisolone", "Ointment-based very potent steroid continuously", "Antifungal shampoo alone for 6 months", "Immediate biologic therapy"], "a": 0, "e": "Potent steroid scalp formulation once daily for up to 4 weeks, with a descaling preparation if scale prevents penetration. Scalp psoriasis: potent steroid in a scalp-friendly formulation (lotion, gel, shampoo, foam) once daily for up to 4 weeks. Consider descaling if scale blocks penetration. Step up with vitamin D analogue or coal tar, or refer if inadequate.", "src": null}, {"id": "derm-t02#7", "cat": "dermatology", "topic": "Psoriasis", "s": "A 60-year-old woman has used clobetasol ointment continuously on her elbows and knees for 7 months. The skin is now thin and the psoriasis flares between applications. What is the most appropriate advice?", "o": ["Continue indefinitely", "Increase frequency to twice daily", "Stop the continuous potent steroid, take a treatment break of about 4 weeks with non-steroid treatment, and review the regimen", "Start oral prednisolone", "Add a more potent steroid"], "a": 2, "e": "Stop the continuous potent steroid, take a treatment break of about 4 weeks with non-steroid treatment, and review the regimen. Continuous prolonged potent steroid causes atrophy and can destabilise psoriasis. NICE advises a break of about 4 weeks between courses, using non-steroid treatment (for example a vitamin D analogue) in the break.", "src": null}, {"id": "derm-t02#8", "cat": "dermatology", "topic": "Psoriasis", "s": "A 29-year-old woman has psoriasis affecting only about 2% of her body surface area but it involves her genital skin and nails. Her DLQI is 14. How should her disease be classified and managed?", "o": ["Mild because BSA is below 3%; no action", "Potentially severe due to high-impact sites and quality-of-life impact; consider dermatology referral", "Needs oral prednisolone", "Needs no assessment of mood", "Manage only with emollients"], "a": 1, "e": "Potentially severe due to high-impact sites and quality-of-life impact; consider dermatology referral. Severity is not judged by BSA alone. Genital and nail involvement and a DLQI above 10 indicate major impact, so consider dermatology referral. Use a mild/moderate steroid (maximum 2 weeks) on genital skin pending specialist advice.", "src": null}, {"id": "derm-t02#9", "cat": "dermatology", "topic": "Psoriasis", "s": "A 31-year-old woman with severe hyperkeratotic psoriasis is considered for acitretin by dermatology. Which statement about pregnancy is correct?", "o": ["Pregnancy is safe to plan 1 month after stopping", "Acitretin is teratogenic; strict pregnancy prevention is needed and pregnancy must be avoided for 3 years after stopping", "Only methotrexate is teratogenic", "No contraception is needed if she is breastfeeding", "Acitretin is a first-line topical"], "a": 1, "e": "Acitretin is teratogenic; strict pregnancy prevention is needed and pregnancy must be avoided for 3 years after stopping. Acitretin is teratogenic and is contraindicated in pregnancy. Pregnancy must be avoided for 3 years after stopping. Methotrexate is also contraindicated in pregnancy.", "src": null}, {"id": "derm-t03#0", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 62-year-old woman has severe vulval itching. Examination shows white, shiny, atrophic plaques in a figure-of-eight around the vulva and anus, with loss of the labia minora. What is the most appropriate first-line treatment?", "o": ["Hydrocortisone 1% cream", "Clobetasol propionate 0.05% ointment", "Topical clotrimazole", "Oestrogen cream alone", "Oral prednisolone"], "a": 1, "e": "Clobetasol propionate 0.05% ointment. Features are classic for female genital lichen sclerosus. First-line is clobetasol propionate 0.05% ointment with a soap substitute and emollient.", "src": null}, {"id": "derm-t03#1", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A woman with vulval lichen sclerosus starts clobetasol 0.05% ointment. Which regimen is correct?", "o": ["Once daily for 1 week then stop", "Once daily month 1, alternate days month 2, twice weekly month 3", "Twice daily for 6 months", "Once weekly for 3 months", "Alternate days continuously, indefinitely"], "a": 1, "e": "Once daily month 1, alternate days month 2, twice weekly month 3. BAD regimen: once daily for a month, alternate days for a month, then twice weekly for a month, with maintenance if disease remains active.", "src": null}, {"id": "derm-t03#2", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 50-year-old man has had intense itching of his nape for 8 months. Examination shows a well-demarcated, thickened, leathery plaque with exaggerated skin markings and excoriations. What is the most appropriate management?", "o": ["Oral antibiotics", "Explain the itch-scratch cycle, emollients, short nails and a potent topical steroid", "Urgent biopsy", "Oral isotretinoin", "Antifungal cream"], "a": 1, "e": "Explain the itch-scratch cycle, emollients, short nails and a potent topical steroid. Lichen simplex chronicus: break the itch-scratch cycle, treat underlying cause and use a potent topical steroid. Antibiotics and biopsy are not routine.", "src": null}, {"id": "derm-t03#3", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 45-year-old has itchy purple, flat-topped, polygonal papules on the flexor wrists with fine white lines on the surface. Which statement is most appropriate?", "o": ["Treat with a potent topical steroid and review medications and hepatitis C risk", "Start methotrexate", "Reassure; no treatment possible", "It is lichen sclerosus", "It requires urgent cancer referral"], "a": 0, "e": "Treat with a potent topical steroid and review medications and hepatitis C risk. Cutaneous lichen planus: potent topical steroid first-line. Review drugs (lichenoid eruption) and consider hepatitis C testing by context.", "src": null}, {"id": "derm-t03#4", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 55-year-old has asymptomatic bilateral white lacy lines on the buccal mucosa found incidentally. What is the most appropriate approach?", "o": ["Urgent biopsy", "Reassure, avoid irritants, maintain oral hygiene and arrange long-term monitoring", "Antifungal for 6 weeks", "Oral antibiotics", "No follow-up needed"], "a": 1, "e": "Reassure, avoid irritants, maintain oral hygiene and arrange long-term monitoring. Reticular oral lichen planus is often asymptomatic. Avoid irritants, maintain hygiene and monitor long term because of the small risk of oral SCC.", "src": null}, {"id": "derm-t03#5", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A patient with known oral lichen planus develops a persistent, indurated ulcer on the lateral tongue that has not healed for 4 weeks. What is the most appropriate next step?", "o": ["Increase topical steroid for 4 more weeks", "Urgent specialist assessment and biopsy", "Antifungal treatment", "Reassure", "Routine review in 6 months"], "a": 1, "e": "Urgent specialist assessment and biopsy. Persistent ulceration or induration in oral lichen planus may indicate squamous cell carcinoma and needs urgent assessment and biopsy.", "src": null}, {"id": "derm-t03#6", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 48-year-old woman has painful vulval erosions with vaginal involvement and early adhesions. Which diagnosis is most likely?", "o": ["Lichen sclerosus", "Lichen simplex chronicus", "Erosive lichen planus", "Candidiasis", "Psoriasis"], "a": 2, "e": "Erosive lichen planus. Vaginal involvement and painful erosions favour erosive lichen planus. Lichen sclerosus usually spares the vagina.", "src": null}, {"id": "derm-t03#7", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 40-year-old uncircumcised man has white sclerotic plaques on the glans, a tightening foreskin and painful erections. What is the most appropriate management?", "o": ["Clobetasol 0.05% ointment once daily for 1-3 months, with urology referral if phimosis persists", "Oral antibiotics only", "Immediate circumcision without treatment", "Topical antifungal", "Reassure"], "a": 0, "e": "Clobetasol 0.05% ointment once daily for 1-3 months, with urology referral if phimosis persists. Male genital lichen sclerosus (BXO): clobetasol 0.05% ointment daily for 1-3 months with emollient. Persistent phimosis needs urology.", "src": null}, {"id": "derm-t03#8", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 66-year-old woman with vulval lichen sclerosus on maintenance clobetasol develops a new non-healing ulcer and nodule on the vulva. What is the most appropriate action?", "o": ["Increase clobetasol and review in 3 months", "Urgent suspected cancer pathway referral and biopsy", "Antifungal cream", "Reassure; this is expected scarring", "Routine gynaecology referral"], "a": 1, "e": "Urgent suspected cancer pathway referral and biopsy. Persistent ulceration or a new nodule in lichen sclerosus suggests vulval SCC. Do not delay referral to complete a steroid trial.", "src": null}, {"id": "derm-t03#9", "cat": "dermatology", "topic": "Lichen simplex, planus and sclerosus", "s": "A 38-year-old has scalp itching with perifollicular erythema, scaling and patches of hair loss with scarring. What is the most appropriate management?", "o": ["Reassure; hair will regrow", "Early dermatology referral for suspected lichen planopilaris", "Antifungal shampoo for 6 months", "Iron supplements only", "Minoxidil only"], "a": 1, "e": "Early dermatology referral for suspected lichen planopilaris. Scarring alopecia suggests lichen planopilaris and risks permanent hair loss, so early dermatology referral is needed.", "src": null}, {"id": "derm-t04#0", "cat": "dermatology", "topic": "Scabies", "s": "A 28-year-old woman has had severe itching for 3 weeks that is worse at night. Her partner is also itching. Examination shows excoriated papules and short linear burrows in the finger webs and wrists. What is the most appropriate management?", "o": ["Hydrocortisone 1% cream and review", "Permethrin 5% cream to the whole body, repeated after 7 days, with simultaneous treatment of her partner", "Oral ivermectin for her only", "Malathion applied to the affected areas only", "Antihistamine and emollient"], "a": 1, "e": "Permethrin 5% cream to the whole body, repeated after 7 days, with simultaneous treatment of her partner. Classical scabies is first treated with permethrin 5% cream to the whole body from the neck down, repeated after 7 days. Her partner must be treated at the same time.", "src": null}, {"id": "derm-t04#1", "cat": "dermatology", "topic": "Scabies", "s": "A mother is diagnosed with scabies. Her two children and husband have no itch. What is the most appropriate advice?", "o": ["Treat only the mother", "Treat the mother and the children who scratch", "Treat all household members at the same time, even without symptoms", "Treat the children only", "Wait to see if they develop symptoms"], "a": 2, "e": "Treat all household members at the same time, even without symptoms. Close contacts may already be infested because symptoms take 4-8 weeks to appear, and untreated contacts reinfect the patient. Treat everyone in the household simultaneously.", "src": null}, {"id": "derm-t04#2", "cat": "dermatology", "topic": "Scabies", "s": "A patient washes his hands 3 hours after applying permethrin. What should he do?", "o": ["Nothing; the treatment is complete", "Reapply the cream to his hands", "Restart the whole course next week", "Switch to oral ivermectin", "Apply hydrocortisone"], "a": 1, "e": "Reapply the cream to his hands. If the hands are washed during the application period, permethrin must be reapplied to the hands.", "src": null}, {"id": "derm-t04#3", "cat": "dermatology", "topic": "Scabies", "s": "A 35-year-old completed a correct course of permethrin with all contacts treated 2 weeks ago. He still has some itching but no new burrows or lesions. What is the most appropriate next step?", "o": ["A second full course of permethrin", "Oral ivermectin", "Explain post-scabetic itch; emollients, with a mild topical steroid or antihistamine if needed", "Skin biopsy", "Malathion 0.5% aqueous"], "a": 2, "e": "Explain post-scabetic itch; emollients, with a mild topical steroid or antihistamine if needed. Itch can persist for 2-6 weeks after successful treatment because of hypersensitivity. Do not repeat scabicides without evidence of active infestation.", "src": null}, {"id": "derm-t04#4", "cat": "dermatology", "topic": "Scabies", "s": "A woman reports persistent itching 4 weeks after permethrin. She has new burrows on the wrists, did not repeat the treatment at 7 days, and her husband was never treated. What is the most appropriate approach?", "o": ["Reassure that this is post-scabetic itch", "Repeat a full, correctly applied course for her and treat all contacts at the same time", "Stop treatment and review in 6 months", "Prescribe oral antibiotics", "Topical steroid only"], "a": 1, "e": "Repeat a full, correctly applied course for her and treat all contacts at the same time. New burrows suggest active infestation or reinfection. Treatment was incomplete (no repeat) and a contact was untreated, so give a complete course with simultaneous contact treatment.", "src": null}, {"id": "derm-t04#5", "cat": "dermatology", "topic": "Scabies", "s": "A 78-year-old care home resident on immunosuppressive therapy has thick hyperkeratotic crusts on her hands and feet. She has little itch. Several staff are itching. What is the most appropriate action?", "o": ["Treat as psoriasis with a potent steroid", "Routine single course of permethrin in primary care", "Same-day specialist assessment for suspected crusted scabies", "Emollients and review in 2 weeks", "Oral antibiotics only"], "a": 2, "e": "Same-day specialist assessment for suspected crusted scabies. Crusted scabies is highly contagious, can occur with little itch and mimics psoriasis. It needs same-day specialist assessment, usually combined ivermectin and permethrin.", "src": null}, {"id": "derm-t04#6", "cat": "dermatology", "topic": "Scabies", "s": "An 8-month-old infant has itchy vesicles and papules on the palms and soles and scalp. Both parents have itchy rashes. Which statement is most appropriate?", "o": ["Scabies is unlikely because the palms and soles are involved", "Scabies is possible; treat the infant including face, scalp and neck as well as the body, and treat the family", "Use oral ivermectin", "Treat the infant only", "Cats are the likely source"], "a": 1, "e": "Scabies is possible; treat the infant including face, scalp and neck as well as the body, and treat the family. Infants can have palm, sole, scalp and face involvement. Permethrin is applied to the whole body including scalp, face and neck (avoiding eyes and mouth), and all household contacts are treated.", "src": null}, {"id": "derm-t04#7", "cat": "dermatology", "topic": "Scabies", "s": "A 26-year-old woman, 20 weeks pregnant, is diagnosed with scabies. Which treatment is most appropriate?", "o": ["Oral ivermectin", "Permethrin 5% cream, repeated after 7 days", "No treatment until delivery", "Alcoholic malathion", "Topical steroid only"], "a": 1, "e": "Permethrin 5% cream, repeated after 7 days. Permethrin 5% is generally preferred in pregnancy. Seek specialist advice before using oral ivermectin.", "src": null}, {"id": "derm-t04#8", "cat": "dermatology", "topic": "Scabies", "s": "A 33-year-old man had scabies treated successfully 8 weeks ago, and contacts were treated. He has persistent itchy reddish-brown nodules on the scrotum with no new burrows. What is the most appropriate management?", "o": ["Repeat oral ivermectin", "Treat as nodular scabies hypersensitivity with a moderate-potency topical steroid and refer if persistent", "Urgent cancer referral", "Repeat permethrin weekly", "Reassure; no treatment exists"], "a": 1, "e": "Treat as nodular scabies hypersensitivity with a moderate-potency topical steroid and refer if persistent. Nodules can persist for weeks or months after cure as a hypersensitivity response. Confirm contacts were treated, use a moderate-potency steroid, and refer if uncertain or persistent.", "src": null}, {"id": "derm-t04#9", "cat": "dermatology", "topic": "Scabies", "s": "A care home manager reports two residents with scabies diagnosed 3 weeks apart, both on the same unit. What is the most appropriate action?", "o": ["Treat only the two residents and wait", "Contact the local Health Protection Team and start an outbreak response, treating cases and contacts in a coordinated way", "Close the home for 8 weeks", "Give all residents oral antibiotics", "Notify as a notifiable disease"], "a": 1, "e": "Contact the local Health Protection Team and start an outbreak response, treating cases and contacts in a coordinated way. Two or more linked cases within 8 weeks in a closed setting should trigger an outbreak response with Health Protection Team support. Do not delay treating individual cases. Scabies is not notifiable in England.", "src": null}, {"id": "derm-t05#0", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 16-year-old boy has blackheads, whiteheads and scattered papules and pustules on his face. He has no scarring. What is the most appropriate first-line treatment?", "o": ["Oral doxycycline alone", "Adapalene 0.1% with benzoyl peroxide 2.5% once daily in the evening for 12 weeks", "Topical clindamycin alone", "Oral isotretinoin", "Daily scrubbing with soap and water"], "a": 1, "e": "Adapalene 0.1% with benzoyl peroxide 2.5% once daily in the evening for 12 weeks. Adapalene + benzoyl peroxide is a NICE first-line option for acne of any severity. Antibiotics alone, and topical clindamycin alone, should be avoided.", "src": null}, {"id": "derm-t05#1", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 24-year-old woman using effective contraception has widespread inflammatory papules and pustules on her face and back with some nodules. What is the most appropriate treatment?", "o": ["Topical benzoyl peroxide alone", "Oral doxycycline alone", "Adapalene with benzoyl peroxide plus oral lymecycline", "Oral trimethoprim alone", "Reassurance"], "a": 2, "e": "Adapalene with benzoyl peroxide plus oral lymecycline. Moderate-severe acne: combine a topical (adapalene + benzoyl peroxide, or azelaic acid) with oral doxycycline or lymecycline. Never use an oral antibiotic alone.", "src": null}, {"id": "derm-t05#2", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 28-year-old woman, 10 weeks pregnant, has mild-moderate inflammatory acne. Which treatment is most appropriate?", "o": ["Adapalene gel", "Oral lymecycline", "Azelaic acid or benzoyl peroxide", "Oral isotretinoin", "Tretinoin with clindamycin"], "a": 2, "e": "Azelaic acid or benzoyl peroxide. Benzoyl peroxide and azelaic acid are generally suitable in pregnancy. Retinoids (topical and oral) and oral tetracyclines are contraindicated.", "src": null}, {"id": "derm-t05#3", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 20-year-old has taken lymecycline with adapalene/benzoyl peroxide for 12 weeks, and his acne is now completely clear. What is the most appropriate next step?", "o": ["Continue both for 12 months", "Stop the oral antibiotic and continue topical treatment", "Stop all treatment", "Switch to doxycycline", "Start isotretinoin"], "a": 1, "e": "Stop the oral antibiotic and continue topical treatment. When acne has cleared at 12 weeks, stop the oral antibiotic and continue topical treatment (maintenance if relapses are frequent).", "src": null}, {"id": "derm-t05#4", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 22-year-old has taken oral doxycycline 100 mg daily alone for 4 months for facial acne, with partial improvement. What is the main problem with his regimen?", "o": ["The dose is too high", "There is no concurrent topical non-antibiotic treatment, raising resistance risk", "He should be on isotretinoin", "Doxycycline cannot treat acne", "He should take it lying down"], "a": 1, "e": "There is no concurrent topical non-antibiotic treatment, raising resistance risk. Oral antibiotics should be combined with a topical treatment such as benzoyl peroxide, adapalene or azelaic acid. Antibiotic courses should not normally exceed 6 months.", "src": null}, {"id": "derm-t05#5", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 17-year-old is starting adapalene with benzoyl peroxide but worries about a dry, irritated face. What is the best advice?", "o": ["Apply it hourly", "Start on alternate days or use short-contact application, then increase as tolerated", "Apply only to individual spots", "Stop all moisturisers", "Scrub the face before each use"], "a": 1, "e": "Start on alternate days or use short-contact application, then increase as tolerated. To reduce irritation, NICE advises alternate-day or short-contact application first, building up to the standard regimen. It is applied to the whole affected area, not just spots.", "src": null}, {"id": "derm-t05#6", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 23-year-old woman has acne with irregular periods and increased facial hair. What is the most appropriate approach?", "o": ["Reassure; this is normal", "Consider PCOS or another androgen-excess disorder, investigate, and consider the COCP if suitable", "Start isotretinoin immediately", "Oral antibiotics alone", "Topical steroids"], "a": 1, "e": "Consider PCOS or another androgen-excess disorder, investigate, and consider the COCP if suitable. Irregular periods and hirsutism with acne suggest hyperandrogenism such as PCOS. Investigate by presentation; the COCP can help acne if there are no contraindications.", "src": null}, {"id": "derm-t05#7", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 19-year-old on isotretinoin from dermatology develops spots and is prescribed lymecycline by another doctor. What is the most appropriate response?", "o": ["Continue both", "Avoid combining them: risk of intracranial hypertension", "Double the isotretinoin dose", "Add doxycycline as well", "No concern"], "a": 1, "e": "Avoid combining them: risk of intracranial hypertension. Isotretinoin must not be combined with tetracyclines because of the risk of intracranial hypertension.", "src": null}, {"id": "derm-t05#8", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 17-year-old boy has sudden severe acne with painful ulcerating nodules and haemorrhagic crusts, fever, malaise and joint pain. What is the most appropriate action?", "o": ["Start doxycycline and review in 12 weeks", "Routine dermatology referral", "Same-day referral to on-call dermatology", "Topical benzoyl peroxide", "Reassure"], "a": 2, "e": "Same-day referral to on-call dermatology. Acne fulminans with systemic features is an emergency requiring same-day referral (assessment within 24 hours).", "src": null}, {"id": "derm-t05#9", "cat": "dermatology", "topic": "Acne vulgaris", "s": "A 21-year-old has severe nodulocystic acne with early scarring despite 12 weeks of adapalene/benzoyl peroxide plus oral lymecycline. What is the most appropriate next step?", "o": ["Repeat the same treatment for a year", "Refer to dermatology for consideration of isotretinoin", "Switch to topical clindamycin alone", "Wait for scarring to settle", "Start oral isotretinoin in primary care"], "a": 1, "e": "Refer to dermatology for consideration of isotretinoin. Nodulocystic acne, scarring, and failure of treatment containing an oral antibiotic warrant dermatology referral. Isotretinoin is initiated and supervised by specialists.", "src": null}, {"id": "derm-t06#0", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 2-year-old has mild eczema with dry skin and occasional itch, sleeping well. What is the most appropriate management?", "o": ["Daily emollients and a mild-potency topical steroid for flares", "Oral cetirizine daily", "Potent steroid daily", "Total IgE", "Emollient bath additive only"], "a": 0, "e": "Daily emollients and a mild-potency topical steroid for flares. Mild eczema: regular emollients plus a mild-potency steroid for flares. No routine antihistamine, no routine IgE, and bath additives are not routinely recommended under 12.", "src": null}, {"id": "derm-t06#1", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 6-year-old has severe eczema flares on the face and neck. Which is the most appropriate steroid advice per NICE?", "o": ["Clobetasol for 4 weeks", "Mild potency; moderate potency for severe flares for 3-5 days only", "Potent steroid for 14 days", "No steroid at all", "Betamethasone valerate 0.1% daily long term"], "a": 1, "e": "Mild potency; moderate potency for severe flares for 3-5 days only. Face and neck in a child under 12: mild potency, with moderate potency only for severe flares and for 3-5 days.", "src": null}, {"id": "derm-t06#2", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 10-year-old has axillary and groin eczema flares. What is the most appropriate approach?", "o": ["Moderate or potent steroid for 7-14 days only", "Very potent steroid for 4 weeks", "Never use steroids", "Antibiotic cream daily", "Oral prednisolone"], "a": 0, "e": "Moderate or potent steroid for 7-14 days only. In children under 12, axillae and groin can receive moderate or potent steroid for 7-14 days only. Very potent steroids need specialist advice.", "src": null}, {"id": "derm-t06#3", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 14-year-old with severe itch and urticaria alongside moderate eczema is not sleeping. What is the most appropriate step?", "o": ["Never prescribe an antihistamine for eczema", "A 1-month trial of a non-sedating antihistamine, reviewing every 3 months if continued", "Long-term sedating antihistamine nightly", "Oral steroids", "Allergy panel for all foods"], "a": 1, "e": "A 1-month trial of a non-sedating antihistamine, reviewing every 3 months if continued. For moderate eczema with severe itch or urticaria, consider a 1-month non-sedating antihistamine trial. Antihistamines do not treat the skin inflammation.", "src": null}, {"id": "derm-t06#4", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 3-year-old has an acute flare with major sleep loss. What is the most appropriate additional measure?", "o": ["Daily non-sedating antihistamine for 6 months", "A sedating age-appropriate antihistamine for 7-14 days", "Oral steroids", "Stop emollients", "Allergy testing"], "a": 1, "e": "A sedating age-appropriate antihistamine for 7-14 days. A short 7-14 day course of a sedating antihistamine may be considered for sleep disturbance during an acute flare in children aged 6 months or over.", "src": null}, {"id": "derm-t06#5", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 5-year-old has weeping, crusted eczema, is well, afebrile, and the eczema is not worsening. What is the most appropriate action?", "o": ["Immediate oral flucloxacillin", "Swab and wait", "Do not routinely prescribe antibiotics; continue emollients and steroid", "Stop the steroid", "Apply an occlusive dressing"], "a": 2, "e": "Do not routinely prescribe antibiotics; continue emollients and steroid. Weeping or crusting alone does not prove infection. Antibiotics are not routine unless clinically significant infection is present.", "src": null}, {"id": "derm-t06#6", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 9-month-old with moderate-severe eczema has faltering growth and vomiting after milk feeds. What is the most appropriate next step?", "o": ["Dairy exclusion for the whole family", "Refer for specialist assessment of suspected food allergy", "Reassure", "Total IgE", "Add a potent steroid"], "a": 1, "e": "Refer for specialist assessment of suspected food allergy. Moderate-severe eczema uncontrolled despite optimal treatment with GI symptoms or faltering growth suggests food allergy; refer rather than start unsupervised exclusion diets.", "src": null}, {"id": "derm-t06#7", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 4-year-old has frequent flares at the same flexural sites about 2-3 times a month despite good flare treatment. What is the most appropriate strategy?", "o": ["Daily potent steroid", "Proactive steroid on those sites on 2 consecutive days each week, with daily emollients, and review in 3-6 months", "Stop emollients", "Antibiotics monthly", "Oral steroids"], "a": 1, "e": "Proactive steroid on those sites on 2 consecutive days each week, with daily emollients, and review in 3-6 months. NICE describes proactive weekend therapy for children with frequent flares, with continued daily emollients and review in 3-6 months.", "src": null}, {"id": "derm-t06#8", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 25-year-old with eczema develops fever and sudden painful uniform vesicles with punched-out erosions on the neck, including near one eye. What is the most appropriate action?", "o": ["Topical aciclovir", "Oral flucloxacillin and review", "Systemic aciclovir now, same-day dermatology and ophthalmology advice", "Wait for PCR", "Potent steroid cream"], "a": 2, "e": "Systemic aciclovir now, same-day dermatology and ophthalmology advice. Suspected eczema herpeticum with periocular involvement: start systemic aciclovir immediately and obtain same-day dermatology and ophthalmology advice without waiting for results.", "src": null}, {"id": "derm-t06#9", "cat": "dermatology", "topic": "Atopic eczema", "s": "A 7-year-old has severe eczema not improving after 1 week of optimal topical treatment. What is the most appropriate referral?", "o": ["Routine referral in 3 months", "Urgent referral within 2 weeks", "Same-day emergency referral", "No referral; extend steroid for 6 weeks", "Allergy referral only"], "a": 1, "e": "Urgent referral within 2 weeks. NICE advises urgent referral (within 2 weeks) for severe childhood eczema not responding after 1 week. Same day is for suspected eczema herpeticum.", "src": null}, {"id": "derm-t07#0", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 32-year-old hairdresser has had hand dermatitis for 8 months, with little improvement despite emollients and a potent topical steroid. What is the most appropriate next step?", "o": ["Increase potent steroid to a very potent steroid indefinitely", "Refer for patch testing", "Oral antihistamine", "Skin biopsy", "Reassure and stop work"], "a": 1, "e": "Refer for patch testing. Persistent hand dermatitis despite adequate treatment, especially in a hairdresser (PPD, rubber, preservatives), needs consideration of allergic contact dermatitis and referral for patch testing, which is mandatory for suspected occupational disease.", "src": null}, {"id": "derm-t07#1", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 28-year-old woman has an itchy eczematous patch under her watch strap and around her umbilicus. What is the most likely cause?", "o": ["Candida infection", "Nickel allergy", "Scabies", "Irritant from sweat only", "Psoriasis"], "a": 1, "e": "Nickel allergy. Nickel in watch backs and jean studs causes allergic contact dermatitis at these sites.", "src": null}, {"id": "derm-t07#2", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 45-year-old develops an itchy, weeping rash along the scalp margin, ears and neck with facial swelling 2 days after using a new hair dye. What is the most likely allergen?", "o": ["Nickel", "Latex", "Para-phenylenediamine (PPD)", "Chromate", "Lanolin"], "a": 2, "e": "Para-phenylenediamine (PPD). PPD in hair dye causes acute allergic contact dermatitis at the hairline, ears and neck with possible facial swelling. Stop the dye, treat and refer for patch testing.", "src": null}, {"id": "derm-t07#3", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A nurse develops urticaria and wheeze within minutes of putting on gloves. What is the most appropriate approach?", "o": ["Patch testing alone", "Think type I latex allergy: avoid latex, urgent allergy assessment", "Potent topical steroid", "Reassure", "Fusidic acid cream"], "a": 1, "e": "Think type I latex allergy: avoid latex, urgent allergy assessment. Immediate symptoms indicate a type I (IgE) reaction, not delayed type IV dermatitis, and carry anaphylaxis risk. Patch testing does not detect type I allergy.", "src": null}, {"id": "derm-t07#4", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A cleaner has dry, cracked, sore hands that burn and improve at weekends and on holiday. What is the most likely diagnosis and best advice?", "o": ["Allergic contact dermatitis; stop all work", "Irritant contact dermatitis; reduce exposure, soap substitute, emollients and protective gloves", "Hand psoriasis; start methotrexate", "Pompholyx; potassium permanganate only", "Tinea; oral terbinafine"], "a": 1, "e": "Irritant contact dermatitis; reduce exposure, soap substitute, emollients and protective gloves. Burning and soreness with improvement away from work suggests irritant dermatitis from wet work. Avoidance, barrier measures and emollients are the foundation.", "src": null}, {"id": "derm-t07#5", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 50-year-old has weeping hand dermatitis with several large tense bullae. What is the most appropriate management?", "o": ["Occlusive potent steroid immediately on infected skin", "Aspirate large bullae, potassium permanganate soaks, swab if infection suspected, and a potent steroid as appropriate", "Oral antihistamine", "Topical antifungal", "Stop all emollients"], "a": 1, "e": "Aspirate large bullae, potassium permanganate soaks, swab if infection suspected, and a potent steroid as appropriate. Aspirate large bullae and dry weeping skin with permanganate soaks (about 1 Permitab in 4 litres, 10-15 minutes, 2-4 times daily); treat infection and use a steroid as indicated.", "src": null}, {"id": "derm-t07#6", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 55-year-old has asymmetrical dry, scaly eczema of the right hand and both feet. What is the most appropriate next step?", "o": ["Potent steroid for 3 months", "Skin scrapings for mycology", "Patch testing", "Oral prednisolone", "Alitretinoin"], "a": 1, "e": "Skin scrapings for mycology. Asymmetrical dry scaling with foot involvement (one hand, two feet) suggests tinea. Confirm with scrapings before steroid treatment.", "src": null}, {"id": "derm-t07#7", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 40-year-old woman has severe hyperkeratotic hand eczema that has not responded to a potent topical steroid or optimal hand care. What is the most appropriate next step?", "o": ["Long-term oral prednisolone", "Dermatology referral for specialist treatment such as alitretinoin or acitretin", "Daily emollient only", "Very potent steroid indefinitely", "Oral antihistamine"], "a": 1, "e": "Dermatology referral for specialist treatment such as alitretinoin or acitretin. Refractory severe disease needs specialist care. Alitretinoin and acitretin are teratogenic and require a pregnancy prevention programme.", "src": null}, {"id": "derm-t07#8", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A GP confirms that a factory worker's hand dermatitis is caused by his work. Which statement is correct?", "o": ["It is not reportable", "It is reportable under RIDDOR; the employer reports and the doctor confirms the diagnosis and alerts the employer", "The GP must report to the HSE personally within 24 hours in all cases", "Only the patient can report", "It is a notifiable disease to UKHSA"], "a": 1, "e": "It is reportable under RIDDOR; the employer reports and the doctor confirms the diagnosis and alerts the employer. Occupational dermatitis is reportable to the HSE under RIDDOR. Responsibility rests with the employer, with confirmation from the treating doctor.", "src": null}, {"id": "derm-t07#9", "cat": "dermatology", "topic": "Contact dermatitis", "s": "A 35-year-old gardener has linear blisters on his forearms that later become hyperpigmented, after handling lime juice and plants in sunshine. What is the most likely diagnosis?", "o": ["Allergic contact dermatitis to nickel", "Phytophotodermatitis", "Eczema herpeticum", "Scabies", "Pompholyx"], "a": 1, "e": "Phytophotodermatitis. Furocoumarin plants or lime juice plus UV cause phytophotodermatitis: linear streaks, blistering and later hyperpigmentation. It is phototoxic, not allergic.", "src": null}];
